describe('Search Input Focus', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should focus the search input when "/" is pressed', () => {
        cy.get('body').type('/');
        cy.get('input[type="search"]').should('be.focused');
    });

    it('should not focus the search input when other keys are pressed', () => {
        cy.get('body').type('a');
        cy.get('input[type="search"]').should('not.be.focused');
    });
});
